<?php
declare(strict_types=1);
function icon(string $name):string{
 $paths=['home'=>'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-8h6v8"/>','thermo'=>'<path d="M10 14.5V5a2 2 0 0 1 4 0v9.5a4 4 0 1 1-4 0Z"/><path d="M12 10v8"/>','history'=>'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v5l3 2"/>','alert'=>'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3v1"/>','box'=>'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M4 10h16M8 6v1m0 7v3"/>','users'=>'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m0-16a3 3 0 0 1 0 6m4 10v-3a6 6 0 0 0-3-5"/>','settings'=>'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>','check'=>'<path d="m5 12 4 4L19 6"/>','plus'=>'<path d="M12 5v14M5 12h14"/>','arrow'=>'<path d="M5 12h14m-5-5 5 5-5 5"/>','book'=>'<path d="M12 5v16M3 3c4 0 6 0 9 2 3-2 5-2 9-2v16c-4 0-6 0-9 2-3-2-5-2-9-2Z"/>','site'=>'<path d="M4 21V7l8-4 8 4v14M8 21v-5h8v5M8 9h1m6 0h1M8 12h1m6 0h1"/>'];
 return '<svg class="icon" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name]??$paths['check']).'</svg>';
}
function badge(string $s):string{$label=['pass'=>'Within limits','warn'=>'Attention','fail'=>'Out of limits','pending'=>'Cooling','overdue'=>'Overdue','recorded'=>'Recorded','upcoming'=>'Upcoming','resolved'=>'Resolved'][$s]??ucfirst($s);return '<span class="badge '.e($s).'">'.e($label).'</span>';}
function admin_head(string $title,string $page='',bool $public=false):void{
 $asset= base_url('assets/');
 echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'.e($title).' · '.APP_NAME.'</title><link rel="icon" href="'.e($asset).'mark.svg" type="image/svg+xml"><link rel="stylesheet" href="'.e($asset).'app.css?v='.APP_VERSION.'"><script src="'.e($asset).'app.js?v='.APP_VERSION.'" defer></script></head><body'.($public?' class="public"':'').'>';
 if($public){echo '<main class="auth-wrap">';return;}
 $s=site();$u=need_user();$nav=[['','home','Overview'],['new','thermo','Record a check'],['alerts','alert','Needs attention'],['history','history','History & reports']];if(manager())$nav=array_merge($nav,[['equipment','box','Equipment & checks'],['limits','settings','Controls & limits']]);if($u['role']==='admin')$nav=array_merge($nav,[['sites','site','Kitchens'],['users','users','Team'],['audit','history','Audit trail'],['updates','settings','Updates']]);$nav[]=['help','book','Kitchen guide'];
 echo '<a class="skip" href="#main">Skip to content</a><aside class="sidebar"><a class="brand" href="'.e(url()).'"><span class="brand-mark"><img src="'.e(base_url('assets/brand/kitchen-safety.svg')).'" width="42" height="42" alt=""></span><span>MustrHQ<small>KITCHEN SAFETY</small></span></a><span class="nav-label">WORKSPACE</span><nav aria-label="Main navigation">';foreach($nav as [$key,$ic,$label])echo '<a '.($page===$key?'aria-current="page"':'').' href="'.e(url($key?'p='.$key:'')).'">'.icon($ic).'<span>'.e($label).'</span></a>';
 echo '</nav><div class="sidebar-foot"><span class="avatar">'.e(mb_substr($u['name'],0,1)).'</span><div><a href="'.e(url('p=account')).'">'.e($u['name']).'</a><small>'.e(ucfirst($u['role'])).'</small></div></div></aside><div class="shell"><header class="topbar"><span class="top-title">Food safety, every shift.</span><form method="post" class="site-switch">'.csrf().'<input type="hidden" name="action" value="switch_site"><label class="sr-only" for="kitchen">Kitchen</label><select id="kitchen" name="site_id">';foreach(sites() as $x)echo '<option value="'.(int)$x['id'].'" '.($x['id']===$s['id']?'selected':'').'>'.e($x['name']).(!$x['active']?' (archived)':'').'</option>';echo '</select><button class="btn small" type="submit">Switch</button></form></header><main id="main" class="main">';
 if(isset($_SESSION['flash'])){echo '<div role="status" class="notice success">'.e($_SESSION['flash']).'</div>';unset($_SESSION['flash']);}
 if(!setting('plan_approved_'.$s['id']))echo '<div class="notice amber">Starting controls need review. A manager should check the limits and schedules against this kitchen’s HACCP plan before live use. '.(manager()?'<a href="'.e(url('p=limits')).'">Review controls</a>':'').'</div>';
 if(!(int)$s['active'])echo '<div class="notice danger">This kitchen is archived. Records remain available; new checks are disabled.</div>';
}
function admin_foot(bool $public=false):void{echo '</main>'.($public?'':'<footer class="footer">MustrHQ Kitchen Safety · v'.APP_VERSION.'<span>Times shown in '.e(site()['timezone']).' · Records stored in UTC</span></footer></div>').'</body></html>';}
function heading(string $eyebrow,string $title,string $desc='',string $extra=''):void{echo '<div class="page-heading"><div><p class="eyebrow">'.e($eyebrow).'</p><h1>'.e($title).'</h1>'.($desc?'<p class="muted">'.e($desc).'</p>':'').'</div>'.$extra.'</div>';}
function input(string $name,string $label,mixed $value='',string $type='text',string $attrs=''):void{echo '<label class="field"><span>'.e($label).'</span><input type="'.e($type).'" name="'.e($name).'" value="'.e($type==='password'?'':(in_array($GLOBALS['page']??'install',['','login','new','record','account','install'],true)?($_POST[$name]??$value):$value)).'" '.$attrs.'></label>';}
function textarea(string $name,string $label,string $value='',bool $required=false):void{echo '<label class="field"><span>'.e($label).'</span><textarea name="'.e($name).'" rows="3" maxlength="5000" '.($required?'required':'').'>'.e(in_array($GLOBALS['page']??'install',['','login','new','record','account','install'],true)?($_POST[$name]??$value):$value).'</textarea></label>';}
function form_start(string $action,string $class=''):void{echo '<form method="post" class="'.e($class).'">'.csrf().'<input type="hidden" name="action" value="'.e($action).'">';if(public_mode()&&in_array($action,['record','event'],true))input('recorded_by','Recorded by (name / initials)',$_SESSION['recorder_name']??'','text','required maxlength="80" autocomplete="off"');}
function hidden(string $name,mixed $value):void{echo '<input type="hidden" name="'.e($name).'" value="'.e($value).'">';}
function button(string $label,string $class='primary'):void{echo '<button class="btn '.e($class).'" type="submit">'.e($label).'</button>';}
function empty_state(string $title,string $text,string $link='',string $label=''):void{echo '<div class="empty">'.icon('check').'<h3>'.e($title).'</h3><p class="muted">'.e($text).'</p>'.($link?'<a class="btn" href="'.e($link).'">'.e($label).'</a>':'').'</div>';}
function open_records(int $site):array{
 $all=rows("SELECT r.* FROM ks_records r WHERE r.site_id=? AND (r.status IN ('fail','warn','pending') OR EXISTS (SELECT 1 FROM ks_events f WHERE f.record_id=r.id AND f.type='recheck' AND JSON_UNQUOTE(JSON_EXTRACT(f.data_json,'$.status'))='fail')) AND NOT EXISTS (SELECT 1 FROM ks_events e WHERE e.record_id=r.id AND e.type='resolve') AND NOT EXISTS (SELECT 1 FROM ks_events e WHERE e.record_id=r.id AND e.type='cooling_complete' AND JSON_UNQUOTE(JSON_EXTRACT(e.data_json,'$.status'))='pass') ORDER BY r.observed_at",[$site]);
 return array_values(array_filter($all,fn($r)=>state($r)['needs_action']));
}
function day_summary(array $site,string $date):array{
 $items=scheduled_items($site,$date);$recorded=count(array_filter($items,fn($x)=>$x['state']==='recorded'));$overdue=count(array_filter($items,fn($x)=>$x['state']==='overdue'));
 $start=parse_local($date.'T00:00',$site['timezone']);$end=$start->setTimezone(new DateTimeZone($site['timezone']))->modify('+1 day')->setTimezone(new DateTimeZone('UTC'));
 return ['scheduled'=>count($items),'recorded_slots'=>$recorded,'overdue_slots'=>$overdue,'upcoming_slots'=>count($items)-$recorded-$overdue,'records'=>(int)(one('SELECT COUNT(*) n FROM ks_records WHERE site_id=? AND observed_at>=? AND observed_at<?',[$site['id'],$start->format('Y-m-d H:i:s'),$end->format('Y-m-d H:i:s')])['n']??0),'open_exceptions'=>count(open_records((int)$site['id'])),'generated_at'=>now()];
}
function records_table(array $records):void{
 if(!$records){empty_state('No records here yet','Saved checks will appear here with their original readings and any follow-up actions.');return;}
 echo '<div class="table-wrap"><table><thead><tr><th>Measured</th><th>Check / item</th><th>Reading</th><th>Result</th><th>Recorded by</th><th><span class="sr-only">Open</span></th></tr></thead><tbody>';
 foreach($records as $r){$st=state($r);echo '<tr><td>'.e(local_time($r['observed_at'],'d M · H:i',$r['timezone'])).'<small>'.($r['late_reason']!==''?'Late entry':'').'</small></td><td><strong>'.e($r['subject']).'</strong><small>'.e(KINDS[$r['kind']]??'Routine check').'</small></td><td class="reading">'.($r['temperature']!==null?e((float)$r['temperature']).'<span>°C</span>':'—').($r['hold_seconds']!==null?'<small>'.(int)$r['hold_seconds'].' sec</small>':'').'</td><td>'.badge($st['status']).($st['closed']?'<small>Resolved · original result kept</small>':'').'</td><td>'.e($r['user_name']).'</td><td><a class="text-link" href="'.e(url('p=record&id='.$r['id'])).'">View '.icon('arrow').'</a></td></tr>';}
 echo '</tbody></table></div>';
}

require_once __DIR__.'/frontend-ui.php';
function head(string $title,string $page='',bool $public=false):void{if(public_mode()&&!$public)frontend_head($title,$page);else admin_head($title,$page,$public);}
function foot(bool $public=false):void{if(public_mode()&&!$public)frontend_foot();else admin_foot($public);}
